def authenticate(email: str, plaintext: str, hasher: PasswordHasher, repo) -> bool:
    record = repo.get_credential(email)
    if record is None:
        return False
    if not hasher.verify(plaintext, record.digest):
        return False
    if hasher.needs_rehash(record.digest):
        repo.update_digest(email, hasher.hash(plaintext))
    return True

def start_login(flow: AuthorizationCodeFlow, session) -> str:
    request = flow.begin(scopes=["openid", "profile"])
    session["oauth_request"] = request
    return request.authorization_url

def finish_login(flow: AuthorizationCodeFlow, session, code: str, state: str) -> dict:
    return flow.exchange(code=code, state=state, stored=session.pop("oauth_request"))

def require_scope(scope: str, introspector: TokenIntrospector, audience: str):
    def dependency(token: str) -> TokenClaims:
        claims = introspector.introspect(token, required_audience=audience)
        if scope not in claims.scopes:
            raise PermissionError(f"missing scope: {scope}")
        return claims
    return dependency

def register_passkey(auth: WebAuthnAuthenticator, user_id: bytes, user_name: str, client_response: dict, challenge: bytes):
    result = auth.finish_registration(challenge=challenge, response=client_response)
    store_credential(user_id=user_id, credential_id=result.credential_id, public_key=result.public_key, sign_count=result.sign_count)

def login(store: SessionStore, response, subject: str) -> None:
    session = store.create(subject=subject)
    response.set_cookie("sid", session.id, secure=True, httponly=True, samesite="lax")

def escalate(store: SessionStore, response, old_sid: str) -> None:
    rotated = store.rotate(old_sid)
    response.set_cookie("sid", rotated.id, secure=True, httponly=True, samesite="lax")

def mutate(guard: CsrfGuard, session_id: str, submitted_token: str, do_work):
    guard.verify(session_id=session_id, submitted_token=submitted_token)
    return do_work()

