def apply_csp(response, policy: ContentSecurityPolicy, nonce: str):
    header_name, header_value = policy.with_nonce(nonce).render_header()
    response.headers[header_name] = header_value

def render_user_mention(encoder: OutputEncoder, user_name: str) -> str:
