    return f"<span class='mention'>@{safe}</span>"

def load_signing_key(vault: SecretsVault):
    version = vault.get("jwt-signing-key")
    return version.material, version.version

def store_pii(env: CryptoEnvelope, record_id: str, pii: bytes):
    sealed = env.seal(plaintext=pii, aad=record_id.encode())
    repo.save(record_id=record_id, ciphertext=sealed.ciphertext, nonce=sealed.nonce, key_id=sealed.key_id)

def issue_token(signer: SignatureVerifier, payload: bytes, key_id: str) -> bytes:
    signature = signer.sign(message=payload, key_id=key_id)
    return payload + b"." + signature

def create_order(validator: InputValidator, raw_body: object, handler) -> object:
