from dataclasses import dataclass
from typing import Protocol

@dataclass(frozen=True)
class RateDecision:
    allowed: bool
    retry_after_seconds: int
    remaining: int

class RateLimiter(Protocol):
    def check(self, key: str, cost: int = 1) -> RateDecision: ...
    def reset(self, key: str) -> None: ...

primitives.consumption_example:
def login(limiter: RateLimiter, username: str, ip: str, attempt):
    decision = limiter.check(key=f"login:{username}:{ip}")
    if not decision.allowed:
        raise TooManyRequests(retry_after=decision.retry_after_seconds)
    return attempt()
